// Format Slack Block Kit message for unattended-upgrade events
const input = $input.first().json;
const body = input.body || input;

const hostname = body.hostname || 'unknown';
const packages = body.packages || '';
const packageCount = body.package_count || 0;
const rebootRequired = body.reboot_required || false;
const rebootPackages = body.reboot_packages || '';
const timestamp = body.timestamp || new Date().toISOString();

// Determine header emoji and text
let headerEmoji = '📦';
let headerText = 'Automatic Package Upgrades';
let statusEmoji = '✅';
let statusText = 'Packages upgraded successfully';

if (rebootRequired) {
  headerEmoji = '🔄';
  headerText = 'Server Reboot Required';
  statusEmoji = '⚠️';
  statusText = 'Kernel update requires manual reboot';
}

// Build Grafana explore URL with LogQL query
const lokiQuery = `{host="${hostname}"} |= "unattended-upgrades"`;
const panes = {
  a: {
    datasource: 'loki',
    queries: [{ refId: 'A', expr: lokiQuery, queryType: 'range' }],
    range: { from: 'now-6h', to: 'now' }
  }
};
const grafanaUrl = `https://grafana.example.org/explore?schemaVersion=1&panes=${encodeURIComponent(JSON.stringify(panes))}&orgId=1`;

// Build blocks array
const blocks = [
  {
    type: 'header',
    text: {
      type: 'plain_text',
      text: `${headerEmoji} ${headerText}`,
      emoji: true
    }
  },
  {
    type: 'section',
    fields: [
      {
        type: 'mrkdwn',
        text: `*Server:*\n\`${hostname}\``
      },
      {
        type: 'mrkdwn',
        text: `*Packages Upgraded:*\n${packageCount}`
      }
    ]
  }
];

// Add packages section if any were upgraded
if (packages && packageCount > 0) {
  blocks.push({
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*Upgraded Packages:*\n\`\`\`${packages}\`\`\``
    }
  });
}

// Add reboot section if required
if (rebootRequired) {
  let rebootText = '*Reboot Required:* Yes';
  if (rebootPackages) {
    rebootText += `\n*Packages requiring reboot:* \`${rebootPackages}\``;
  }
  blocks.push({
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: rebootText
    }
  });
}

// Add context footer
blocks.push({
  type: 'context',
  elements: [
    {
      type: 'mrkdwn',
      text: `${statusEmoji} ${statusText} | ${timestamp}`
    }
  ]
});

// Add View Logs button
blocks.push({
  type: 'actions',
  elements: [
    {
      type: 'button',
      text: {
        type: 'plain_text',
        text: 'View Logs',
        emoji: true
      },
      url: grafanaUrl
    }
  ]
});

const fallbackText = `${headerEmoji} ${headerText}: ${hostname} - ${packageCount} packages upgraded${rebootRequired ? ' (reboot required)' : ''}`;

return [{ json: { blocks, fallbackText } }];
